/* cc900-data: DSP_DetuneCurve_SignedFP 12 = FPConst_DSP_DetuneCurve_Finalize_Q23One */
long DSP_DetuneCurve_SignedFP(unsigned char **pp, long v)
{
    float y;
    float f;
    long r;
    register long x;

    x = v;
    if (ABS(x) <= 10) {
        f = ABS(x) * 2.0F;
    } else if (ABS(x) <= 19) {
        f = ABS(x) * 20.0F - 180.0F;
    } else if (ABS(x) <= 31) {
        f = ABS(x) * 100.0F - 1700.0F;
    } else {
        f = ABS(x) * 200.0F - 4800.0F;
    }
    if (x < 0) {
        f = -f;
    }
    y = (1.0 - pow(2.0, f / 2400.0F)) / 2400.0;
    r = y * 8388608.0F;
    return r;
}

